finance_asset_opening_entry_claims.declaration:
CREATE TABLE finance_asset_opening_entry_claims (
    entry_id uuid PRIMARY KEY REFERENCES gl_entries(id),group_id uuid NOT NULL REFERENCES finance_asset_opening_groups(id)
)

finance_gl_period_versions.declaration:
CREATE TABLE finance_gl_period_versions (
    period char(7) PRIMARY KEY CHECK(period~'^[0-9]{4}-(0[1-9]|1[0-2])$'),revision bigint NOT NULL DEFAULT 0
)

finance_payroll_one_existing_non_cash_cl.declaration:
CREATE UNIQUE INDEX finance_payroll_one_existing_non_cash_claim ON finance_payroll_accruals(voucher_id)
 WHERE mode='EXISTING_CONFIRMED_LIABILITY' AND net_amount=0 AND gross_amount>0
   AND instruction_snapshot->>'existingLiabilityBasis'='NET_AFTER_DEDUCTIONS';

idx_finance_statement_material_review.declaration:
CREATE INDEX idx_finance_statement_material_review
 ON finance_statement_document_reviews(material_context_id,date_from,date_to,id)
 WHERE material_context_id IS NOT NULL;
